data.value:
Select HRMS_BonusDetail.BonusHeaderID,HRMS_BonusDetail.EmployeeID,HRMS_BonusDetail.BonusDetailID,HRMS_BonusDetail.CompanyID ,HRMS_BonusDetail.PeriodID,GrossSalary,HRMS_BonusDetail.BasicSalary,HRMS_BonusDetail.BonusAmount as Bonus,HRMS_BonusHeader.NoOfDays as NoOfDays,HRMS_BonusDetail.BonusAbsent ,HRMS_BonusDetail.CreateDate ,HRMS_BonusDetail.CreatedBy ,HRMS_BonusDetail.UpdateDate ,HRMS_BonusDetail.UpdatedBy ,HRMS_Set_Employee.FullName as EmployeeName ,HRMS_BonusDetail.DesignationID ,SET_Designation.DesignationName , SET_Department.DepartmentID ,SET_Department.DepartmentName ,HRMS_BonusDetail.Eligibility ,HRMS_BonusDetail.InComeTax, HRMS_BonusDetail.NetBonusAmount, HRMS_Employement_Status.Description as EmployeeStatusName ,HRMS_Set_Employee.EmployeeCode ,HRMS_Set_Employee.FullName ,HRMS_BonusDetail.NoOfDays as PresentDays ,HRMS_BonusDetail.ArrearOfBonus, HRMS_BonusDetail.DeductionOfBonus ,HRMS_BonusDetail.AdvanceSalary ,SET_Business.BusinessName +'-'+ SET_OperatingUnit.OperatingUnitName as CompanyName ,HRMS_Set_Employee.JoiningDate ,HRMS_Set_Employee.FK_BankAccountID ,HRMS_Set_Employee.FK_BankBranchID ,AR_SET_BankAccount.BankAccountName ,EmpAccountNo,BankName ,HRMS_BonusDetail.CreatedByValue as UserID ,('BONUS SLIP FOR THE MONTH OF '+ Upper(DATEName(MONTH,CurrentManulDate)) +' YEAR '+ Convert(Varchar(11),DATEPART(YEAR,CurrentManulDate))) as BankBranchName ,HRMS_Set_Employee.IBanNo FROM HRMS_BonusDetail Left Join HRMS_BonusHeader on HRMS_BonusHeader.BonusID = HRMS_BonusDetail.BonusHeaderID And HRMS_BonusHeader.CompanyID = HRMS_BonusDetail.CompanyID And HRMS_BonusHeader.PeriodID = HRMS_BonusDetail.PeriodID inner join HRMS_Set_Employee on HRMS_Set_Employee.PersonID = HRMS_BonusDetail.EmployeeID and HRMS_Set_Employee.COmpanyID = HRMS_BonusHeader.COmpanyID LEFT join SET_Designation on SET_Designation.DesignationID = HRMS_BonusDetail.DesignationID LEFT join SET_Department on SET_Department.DepartmentID = HRMS_Set_Employee.FK_DepartmentID Left Join HRMS_Employement_Status on HRMS_Employement_Status.StatusID =HRMS_BonusHeader.EmployStatusID And HRMS_Employement_Status.Status=1 left Join Set_Company on Set_Company.CompanyId=HRMS_BonusDetail.CompanyID left Join SET_Business on SET_Business.IsActive = 1 inner Join SET_OperatingUnit on SET_OperatingUnit.OperatingUnitId= Set_Company.OperatingUnitId left join AR_SET_BankBranch on AR_SET_BankBranch.BankBranchID = HRMS_SET_Employee.FK_BankBranchID and AR_SET_BankBranch.status =1
left JOIN AR_SET_BankAccount on HRMS_SET_Employee.FK_BankBranchID = AR_SET_BankAccount.BankBranchID AND AR_SET_BankAccount.Status = 1 and AR_SET_BankAccount.CompanyID= HRMS_Set_Employee.CompanyID
left JOIN AR_SET_Bank on AR_SET_BankBranch.BankID = AR_SET_Bank.BankID and AR_SET_Bank.Status = 1 Where HRMS_BonusDetail.Status=1 and HRMS_BonusHeader.MillStartDate = @DateFrom and HRMS_BonusHeader.CurrentManulDate = @DateTo and HRMS_BonusDetail.CompanyID = @CompanyID {0}
